function composeDashboard(sections, viewportWidth) {
  if (!Array.isArray(sections)) {
    throw new TypeError('sections must be an array');
  }
  if (!Number.isInteger(viewportWidth) || viewportWidth < 0) {
    throw new TypeError('viewportWidth must be a non-negative integer');
  }

  const keys = new Set();
  const copied = sections.map((section) => {
    if (
      section === null ||
      typeof section !== 'object' ||
      typeof section.key !== 'string' ||
      section.key.length === 0 ||
      typeof section.heading !== 'string' ||
      section.heading.length === 0 ||
      typeof section.content !== 'string' ||
      section.content.length === 0
    ) {
      throw new TypeError('each section must contain non-empty strings');
    }
    if (keys.has(section.key)) {
      throw new TypeError('section keys must be unique');
    }
    keys.add(section.key);
    return { key: section.key, heading: section.heading, content: section.content };
  });

  const paired = viewportWidth > 640;
  const size = paired ? 2 : 1;
  const rows = [];
  for (let index = 0; index < copied.length; index += size) {
    rows.push(copied.slice(index, index + size).map((section) => ({ ...section })));
  }

  return { mode: paired ? 'paired' : 'single', rows };
}

module.exports = { composeDashboard };

