'use strict';
const assert = require('node:assert');
const api = require('./solution');
assert.deepStrictEqual(Object.keys(api).sort(), ['composeDashboard']);
const { composeDashboard } = api;

for (const badSections of [null, undefined, {}, 'x', 3]) {
  assert.throws(() => composeDashboard(badSections, 640), TypeError);
}
for (const badWidth of [-1, 1.5, NaN, Infinity, '640', null, undefined]) {
  assert.throws(() => composeDashboard([], badWidth), TypeError);
}
for (const sections of [
  [null], [[]], [{}],
  [{ key: '', heading: 'H', content: 'C' }],
  [{ key: 'k', heading: '', content: 'C' }],
  [{ key: 'k', heading: 'H', content: '' }],
  [{ key: 1, heading: 'H', content: 'C' }],
  [{ key: 'k', heading: 1, content: 'C' }],
  [{ key: 'k', heading: 'H', content: 1 }],
  [{ key: 'x', heading: 'H1', content: 'C1' }, { key: 'x', heading: 'H2', content: 'C2' }]
]) {
  assert.throws(() => composeDashboard(sections, 640), TypeError);
}

assert.deepStrictEqual(composeDashboard([], 0), { mode: 'single', rows: [] });
assert.deepStrictEqual(composeDashboard([], 640), { mode: 'paired', rows: [] });
const sections = [
  { key: 'a', heading: 'First', content: 'One' },
  { key: 'b', heading: 'Second', content: 'Two' },
  { key: 'c', heading: 'Third', content: 'Three' }
];
assert.deepStrictEqual(composeDashboard(sections, 639), {
  mode: 'single',
  rows: [
    [{ key: 'a', heading: 'First', content: 'One' }],
    [{ key: 'b', heading: 'Second', content: 'Two' }],
    [{ key: 'c', heading: 'Third', content: 'Three' }]
  ]
});
const paired = composeDashboard(sections, 640);
assert.deepStrictEqual(paired, {
  mode: 'paired',
  rows: [
    [
      { key: 'a', heading: 'First', content: 'One' },
      { key: 'b', heading: 'Second', content: 'Two' }
    ],
    [{ key: 'c', heading: 'Third', content: 'Three' }]
  ]
});
sections[0].heading = 'changed input';
sections.push({ key: 'd', heading: 'Fourth', content: 'Four' });
assert.strictEqual(paired.rows[0][0].heading, 'First');
assert.strictEqual(paired.rows.length, 2);
paired.rows[0][0].content = 'changed result';
paired.rows[0].pop();
assert.deepStrictEqual(composeDashboard([
  { key: 'a', heading: 'First', content: 'One' },
  { key: 'b', heading: 'Second', content: 'Two' }
], 900).rows, [[
  { key: 'a', heading: 'First', content: 'One' },
  { key: 'b', heading: 'Second', content: 'Two' }
]]);

